\"\"\"Verify actual authored SVG dissection using exact rational arithmetic.\"\"\"
from fractions import Fraction as F
from pathlib import Path
from itertools import combinations
import re
import xml.etree.ElementTree as ET

source = Path('compositions/proof.html').read_text()
svg = ET.fromstring(re.search(r'<svg\\b.*?</svg>', source, re.S).group())
ns = {'s':'http://www.w3.org/2000/svg'}
def points(s): return [tuple(map(F, p.split(','))) for p in s.split()]
def signed_area(p):
    return sum(a[0]*b[1]-a[1]*b[0] for a,b in zip(p,p[1:]+p[:1]))/2 if len(p)>2 else F(0)
def area(p): return abs(signed_area(p))
def cross(a,b,c): return (b[0]-a[0])*(c[1]-a[1])-(b[1]-a[1])*(c[0]-a[0])
def intersection(subject, clip):
    if signed_area(clip)<0: clip=clip[::-1]
    output=subject[:]
    for a,b in zip(clip,clip[1:]+clip[:1]):
        inp,output=output,[]
        if not inp: return []
        for p,q in zip(inp,inp[1:]+inp[:1]):
            dp,dq=cross(a,b,p),cross(a,b,q)
            if dp>=0: output.append(p)
            if (dp>=0)"'!=(dq>=0):
                t=dp/(dp-dq)
                output.append((p[0]+t*(q[0]-p[0]),p[1]+t*(q[1]-p[1])))
    return output

src=[]; dst=[]
for g in svg.findall('"'.//s:g',ns):
    if 'data-dx' not in g.attrib: continue
    poly=g.find('s:polygon',ns)
    if poly is not None: p=points(poly.attrib['points'])
    else:
        r=g.find('s:rect',ns); x,y,w,h=[F(r.attrib[k]) for k in ('x','y','width','height')]
        p=[(x,y),(x+w,y),(x+w,y+h),(x,y+h)]
    dx,dy=F(g.attrib['data-dx']),F(g.attrib['data-dy'])
    q=[(x+dx,y+dy) for x,y in p]
    assert area(p)==area(q),g.attrib['id']
    src.append((g.attrib['id'],p)); dst.append((g.attrib['id'],q))

target=points(svg.find('.//s:polygon[@id=\"proof-target-wash\"]',ns).attrib['points'])
assert len(src)==5
assert sorted(area(p)/(75*75) for _,p in src)==[4,4,4,4,9]
assert sum(area(p) for _,p in src)==area(target)==F(140625)
for stage in (src,dst):
    for (a,p),(b,q) in combinations(stage,2):
        assert area(intersection(p,q))==0,('overlap',a,b)
for name,p in dst:
    assert area(intersection(p,target))==area(p),('outside target',name)
print('PASS: five rigid pieces; source areas 4+4+4+4+9=25; destination area 25; no overlaps; exact complete target coverage.')
